import { _decorator, Component } from 'cc';
import { Debug } from '../../Utils/Debug';
import { IReel } from './UniReel/Interface/IReel';
import { UniReel } from './UniReel/UniReel';
const { ccclass, property } = _decorator;

@ccclass('ReelManager')
export class ReelManager<ReelType extends IReel> extends Component {
    @property({ type: UniReel, visible: true })
    protected _reelList: ReelType[] = [];

    public get reelAmount(): number {
        return this._reelList.length;
    }

    public init(): void {
        for (let index = 0; index < this._reelList.length; index++) {
            let reel = this._reelList[index];
            reel.init(index);
        }
    }

    public add(reel: ReelType, index?: number): void {
        if (index) {
            this._reelList[index] = reel;
        }
        else {
            this._reelList.push(reel);
        }
    }

    public remove(index: number): void {
        this._reelList.splice(index, 1);
    }

    public getReel(index: number): ReelType {
        return this._reelList[index];
    }

    public getByState(reelState: number): ReelType[] {
        let reels: ReelType[] = [];

        for (let reelID = 0; reelID < this._reelList.length; reelID++) {
            const reel = this._reelList[reelID];
            if (reel.currentRoundState === reelState) {
                reels.push(reel);
            }
        }

        return reels;
    }

    public getReelState(reelID: number): number {
        return this._reelList[reelID].currentRoundState;
    }
}